<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { BrainCircuit, CircleDot, Fingerprint, Flag, HeartCrack, Network, Sparkles, TriangleAlert, Waves } from "@lucide/vue";
import { api, bestEffort, formatNumber, json } from "../api";
import EmptyState from "../components/EmptyState.vue";

const emit = defineEmits<{ notify: [tone: "success"|"error"|"info", title: string, detail?: string] }>();
const overview = ref<any>(null); const subject = ref<any>(null); const desires = ref<any[]>([]); const relations = ref<any[]>([]); const contradictions = ref<any[]>([]); const identity = ref<any>(null); const sylann = ref<any>(null); const drift = ref<any>(null); const loading = ref(true); const driftBusy = ref(false);
const stability = computed(() => Math.round(Number(overview.value?.identity_stability || identity.value?.stability || 0) * 100));
const driftPct = (spent:number, budget:number) => budget>0 ? Math.min(100, Math.round(Number(spent||0)/Number(budget)*100)) : 0;
async function load(){loading.value=true;try{const [o,s,d,r,c,i,h,dr]=await Promise.all([bestEffort(api<any>("/api/cognitive/overview"),null),bestEffort(api<any>("/api/subject"),null),bestEffort(api<any>("/api/cognitive/desires"),{items:[]}),bestEffort(api<any>("/api/cognitive/relations"),{items:[]}),bestEffort(api<any>("/api/cognitive/contradictions"),{items:[]}),bestEffort(api<any>("/api/cognitive/identity"),null),bestEffort(api<any>("/api/health"),{}),bestEffort(api<any>("/api/cognitive/drift"),null)]);overview.value=o;subject.value=s;desires.value=d.items||[];relations.value=r.items||[];contradictions.value=c.items||[];identity.value=i;sylann.value=h.sylann||null;drift.value=dr||o?.drift||i?.drift||null;}finally{loading.value=false}}
async function driftAction(action:string, extra:Record<string,unknown>={}){driftBusy.value=true;try{const r=await api<any>("/api/cognitive/drift",json("POST",{action,...extra}));drift.value=r.status||drift.value;emit("notify","success",action==="pause"?"已暂停反刍":action==="resume"?"已恢复反刍":action==="purge"?"已清粘滞笔记":"漂移操作完成");await load()}catch(e:any){emit("notify","error","漂移操作失败",e.message)}finally{driftBusy.value=false}}
onMounted(load);
</script>

<template><section class="page cognition-page">
  <div class="page-heading"><div><span class="eyebrow">inner world</span><h1>她的内心正在发生什么？</h1><p>认知状态是观察窗口，不是几段原始 Prompt；变化、冲突与稳定性都有自己的位置。</p></div></div>
  <div class="mind-map panel">
    <div class="mind-center"><span class="mind-rings"><i/><b/><em/></span><div><small>IDENTITY COHERENCE</small><strong>{{ stability || '—' }}%</strong><span>{{ overview?.persona_has_proposal ? '存在待审人格提案' : '人格核心保持稳定' }}</span></div></div>
    <div class="mind-facts"><article><Fingerprint :size="18"/><span><small>人格上下文</small><strong>{{ formatNumber(overview?.persona_prompt_len) }} 字</strong></span></article><article><Network :size="18"/><span><small>关系模型</small><strong>{{ formatNumber(overview?.relations) }} 人</strong></span></article><article><HeartCrack :size="18"/><span><small>伤痕</small><strong>{{ formatNumber(overview?.scars) }} 条</strong></span></article><article><TriangleAlert :size="18"/><span><small>未解矛盾</small><strong>{{ formatNumber(overview?.contradictions) }} 项</strong></span></article></div>
  </div>
  <section class="panel drift-panel">
    <div class="panel-head"><div><strong>人格漂移预算</strong><span>软漂移只改自我笔记；核心 persona 不会静默改写</span></div><Waves :size="18"/></div>
    <div v-if="drift" class="drift-metrics">
      <article><small>General 日池</small><strong>{{ Number(drift.daily_spent||0).toFixed(2) }} / {{ Number(drift.daily_budget||0).toFixed(2) }}</strong><span><i :style="{width: driftPct(drift.daily_spent, drift.daily_budget)+'%'}"/></span></article>
      <article><small>自我修正池</small><strong>{{ Number(drift.self_correction_spent||0).toFixed(2) }} / {{ Number(drift.self_correction_daily_budget||0).toFixed(2) }}</strong><span><i :style="{width: driftPct(drift.self_correction_spent, drift.self_correction_daily_budget)+'%'}"/></span></article>
      <article><small>7 日滚动窗</small><strong>{{ Number(drift.window_spent||0).toFixed(2) }} / {{ Number(drift.window_ceiling||0).toFixed(2) }}</strong><span><i :style="{width: driftPct(drift.window_spent, drift.window_ceiling)+'%'}"/></span></article>
      <article><small>笔记 / 反刍</small><strong>{{ formatNumber(drift.notes_lines) }} 行</strong><span>{{ drift.rumination_paused ? '反刍已暂停' : '反刍运行中' }} · 拒因 {{ drift.last_reject?.reason || '—' }}</span></article>
    </div>
    <div class="drift-actions">
      <button class="action-button subtle" :disabled="driftBusy" @click="driftAction('pause',{hours:24})">暂停反刍 24h</button>
      <button class="action-button subtle" :disabled="driftBusy" @click="driftAction('resume')">恢复反刍</button>
      <button class="action-button subtle" :disabled="driftBusy" @click="driftAction('purge')">清粘滞笔记</button>
    </div>
    <EmptyState v-if="!drift && !loading" title="暂无漂移状态" detail="启动后会在此显示日预算与 7 日窗用量。" />
  </section>
  <div class="cognition-grid">
    <section class="panel"><div class="panel-head"><div><strong>欲望与内在动机</strong><span>当前真正影响行动倾向的目标</span></div><Sparkles :size="18"/></div><div v-if="desires.length" class="desire-list"><article v-for="item in desires.slice(0,8)" :key="item.id || item.content"><div><strong>{{ item.content }}</strong><small>{{ item.resolved ? '已解决' : '仍在驱动行为' }}</small></div><span><i :style="{width:`${Math.round(Number(item.intensity||0)*100)}%`}"/></span></article></div><EmptyState v-else title="内心很安静" detail="目前没有活跃到需要展示的欲望。"/></section>
    <section class="panel"><div class="panel-head"><div><strong>关系世界</strong><span>亲密度与信任会随互动缓慢变化</span></div><Network :size="18"/></div><div v-if="relations.length" class="relation-list"><article v-for="item in relations.slice(0,8)" :key="item.user_id"><span class="avatar">{{ String(item.user_id).slice(-2) }}</span><div><strong>QQ {{ item.user_id }}</strong><small>熟悉度 {{ Number(item.familiarity || item.closeness || 0).toFixed(2) }} · 信任 {{ Number(item.trust || 0).toFixed(2) }}</small></div></article></div><EmptyState v-else title="关系还在形成" detail="稳定互动后，这里会出现脱敏后的关系轮廓。"/></section>
  </div>
  <section class="panel intent-panel"><div class="panel-head"><div><strong>正在选择的行动</strong><span>每个主动动作都先进入主体账本，只有 QQ 出站确认后才会完成。</span></div><Flag :size="18"/></div><div v-if="subject?.active_intents?.length" class="intent-list"><article v-for="item in subject.active_intents" :key="item.id"><span class="intent-signal" :class="item.status"/><div><small>{{ item.source === 'owner' ? 'Owner 指派' : item.source === 'calendar' ? '日历提醒' : item.source === 'legacy_agenda' ? '历史议程' : '系统意图' }}</small><strong>{{ item.content }}</strong><span>目标群 {{ item.target_id }} · 已尝试 {{ item.attempts || 0 }} 次</span></div><em>{{ item.status === 'selected' ? '准备表达' : item.status === 'dispatched' ? '正在确认' : '等待时机' }}</em></article></div><EmptyState v-else title="暂无待表达事项" detail="新的日历提醒、订阅通知和 Owner 指令会先在这里获得可追溯的行动身份。"/></section>
  <section class="panel sylann-panel">
    <div class="panel-head"><div><strong>Sylann 表达回路</strong><span>只展示运行指标，不暴露原始会话内容</span></div><BrainCircuit :size="18"/></div>
    <div class="sylann-metrics">
      <article><small>模式</small><strong>{{ sylann?.mode || '未启用' }}</strong><span>{{ sylann?.engine === 'running' ? '引擎运行中' : '等待引擎' }}</span></article>
      <article><small>观测 / 表达</small><strong>{{ formatNumber(sylann?.observations) }} / {{ formatNumber(sylann?.expression_hints) }}</strong><span>命中率 {{ Math.round(Number(sylann?.expression_hint_rate || 0) * 100) }}%</span></article>
      <article><small>出站成功率</small><strong>{{ Math.round(Number(sylann?.response_success_rate || 0) * 100) }}%</strong><span>{{ formatNumber(sylann?.responses) }} 次反馈 · {{ sylann?.response_failures || 0 }} 次失败</span></article>
      <article><small>评估进度</small><strong>{{ Math.min(100, Math.round(Number(sylann?.observations || 0) / Number(sylann?.evaluation_sample_target || 100) * 100)) }}%</strong><span>{{ sylann?.ready_for_evaluation ? '达到评估样本线' : '继续积累样本' }}</span></article>
    </div>
  </section>
  <div class="section-title"><div><h2>需要慢慢消化的矛盾</h2><p>系统不会用一条新消息粗暴覆盖旧事实。</p></div></div>
  <div v-if="contradictions.length" class="contradiction-list"><article v-for="item in contradictions.slice(0,8)" :key="item.timestamp" class="panel"><CircleDot :size="18"/><div><strong>{{ item.description || item.current_text || '发现事实不一致' }}</strong><small>用户 {{ item.user_id || '未知' }} · 群 {{ item.group_id || '私聊' }}</small></div></article></div><EmptyState v-else title="当前没有未解矛盾" detail="新旧事实保持一致，或已经被妥善调和。"/>
</section></template>

<style scoped>
