.mind-map{min-height:260px;padding:clamp(25px,5vw,48px);display:grid;grid-template-columns:1.1fr 1fr;align-items:center;gap:35px;background:radial-gradient(circle at 18% 50%,rgba(180,154,255,.14),transparent 35%),linear-gradient(125deg,#241a31,#17131f)}.mind-center{display:flex;align-items:center;gap:28px}.mind-rings{position:relative;width:130px;height:130px;flex:0 0 auto;display:grid;place-items:center}.mind-rings i,.mind-rings b,.mind-rings em{position:absolute;border-radius:50%;border:1px solid rgba(180,154,255,.35)}.mind-rings i{inset:0;animation:spin 14s linear infinite}.mind-rings b{inset:19px;border-color:rgba(255,143,184,.28);animation:spin 9s linear reverse infinite}.mind-rings em{inset:42px;border:0;background:radial-gradient(circle at 36% 32%,#fff,var(--purple) 20%,#5e437d 72%);box-shadow:0 0 35px rgba(180,154,255,.35);animation:breathe 3s ease-in-out infinite}@keyframes breathe{50%{transform:scale(1.08)}}.mind-center small,.mind-center strong,.mind-center div>span{display:block}.mind-center small{color:var(--purple);font:760 9px ui-monospace,monospace;letter-spacing:1.2px}.mind-center strong{margin:8px 0 4px;font:760 39px Georgia,serif}.mind-center div>span{color:var(--muted);font-size:10px}.mind-facts{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:var(--line)}.mind-facts article{min-height:78px;padding:16px;background:#1a1524;display:flex;align-items:center;gap:11px}.mind-facts svg{color:var(--pink)}.mind-facts small,.mind-facts strong{display:block}.mind-facts small{color:var(--muted);font-size:8px}.mind-facts strong{margin-top:4px;font-size:11px}.cognition-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:14px}.panel-head svg{color:var(--purple)}.desire-list,.relation-list{padding:8px 18px}.desire-list article{padding:12px 0;border-bottom:1px solid var(--line)}.desire-list strong,.desire-list small{display:block}.desire-list strong{font-size:11px}.desire-list small{margin-top:4px;color:var(--muted);font-size:8px}.desire-list article>span{display:block;height:3px;margin-top:10px;background:rgba(255,255,255,.06)}.desire-list i{display:block;height:100%;background:linear-gradient(90deg,var(--pink),var(--purple))}.relation-list article{min-height:58px;display:flex;align-items:center;gap:11px;border-bottom:1px solid var(--line)}.avatar{width:31px;height:31px;display:grid;place-items:center;background:rgba(180,154,255,.12);color:var(--purple);font-size:9px}.relation-list strong,.relation-list small{display:block}.relation-list strong{font-size:10px}.relation-list small{margin-top:4px;color:var(--muted);font-size:8px}.contradiction-list{display:grid;grid-template-columns:1fr 1fr;gap:10px}.contradiction-list article{min-height:75px;padding:16px;display:flex;align-items:flex-start;gap:11px}.contradiction-list svg{color:var(--amber);flex:0 0 auto}.contradiction-list strong,.contradiction-list small{display:block}.contradiction-list strong{font-size:10px;line-height:1.5}.contradiction-list small{margin-top:5px;color:var(--muted);font-size:8px}@media(max-width:800px){.mind-map,.cognition-grid{grid-template-columns:1fr}.mind-center{display:block}.mind-rings{margin-bottom:20px}.contradiction-list{grid-template-columns:1fr}}
.sylann-panel{margin-top:14px}.sylann-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:var(--line)}.sylann-metrics article{min-height:92px;padding:15px;background:#1a1524}.sylann-metrics small,.sylann-metrics strong,.sylann-metrics span{display:block}.sylann-metrics small{color:var(--muted);font-size:8px}.sylann-metrics strong{margin-top:8px;color:var(--lime);font:720 18px Georgia,serif}.sylann-metrics span{margin-top:5px;color:var(--muted);font-size:8px}@media(max-width:800px){.sylann-metrics{grid-template-columns:1fr 1fr}}@media(max-width:480px){.sylann-metrics{grid-template-columns:1fr}}
